package main

import (
	"fmt"
)

// levenshteinDistance calculates the Levenshtein distance between two strings.
func levenshteinDistance(a, b string) int {
	m, n := len(a), len(b)

	// Create a slice to store the previous row.
	prev := make([]int, n+1)

	// Initialize the first row.
	for j := 0; j <= n; j++ {
		prev[j] = j
	}

	// Fill in the rest of the matrix.
	for i := 1; i <= m; i++ {
		curr := make([]int, n+1)
		curr[0] = i
		for j := 1; j <= n; j++ {
			cost := 0
			if a[i-1] != b[j-1] {
				cost = 1
			}
			curr[j] = min(min(prev[j]+1, curr[j-1]+1), prev[j-1]+cost)
		}
		prev = curr
	}

	return prev[n]
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func main() {
	a := "kitten"
	b := "sitting"
	fmt.Printf("Levenshtein distance between '%s' and '%s': %d\n", a, b, levenshteinDistance(a, b))
}
```

