/**
 * Debounces an async API call with cancellation support.
 * 
 * @param {function} apiCall - The async API call to debounce.
 * @param {number} [delay=500] - The debounce delay in milliseconds.
 * @returns {function} - The debounced async API call function.
 */
function debounceAsyncApiCall(apiCall, delay = 500) {
  let timeoutId = null;
  let abortController = null;

  return async function(...args) {
    // Cancel any ongoing request and timeout
    if (abortController) {
      abortController.abort();
    }

    return new Promise((resolve, reject) => {
      timeoutId = setTimeout(async () => {
        // Create a new AbortController for this invocation
        abortController = new AbortController();
        const signal = abortController.signal;

        try {
          const response = await apiCall(...args, { signal });
          resolve(response);
        } catch (error) {
          if (error.name === 'AbortError') {
            // Request was aborted, not an issue
            // console.log('Request was aborted.');
          } else {
            reject(error);
          }
        } finally {
          // Cleanup
          abortController = null;
        }
      }, delay);

      // Clear the timeout if called again within the delay period
      return {
        cancel: () => {
          clearTimeout(timeoutId);
          timeoutId = null;
        }
      };
    });
  };
}
